import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';
import { translations } from '../../translations';

const ContactUsHeader = ({
  showTitle = false,
  titleKey = 'contactUs',
  children
}) => {
  const { language, isRTL, toggleLanguage } = useLanguage();
  const t = translations[language];
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <header
      className="w-full text-white overflow-x-hidden"
      style={{
        padding: isMobile ? '15px' : '50px 40px',
        fontFamily: "'Rubik', sans-serif",
        background: 'linear-gradient(to right, rgb(0, 84, 147), rgb(51, 177, 215))'
      }}
    >
      <div className="max-w-[1895px] mx-auto w-full">
        {/* Desktop Navigation Row */}
        <div className="hidden md:flex justify-between items-center w-full gap-2 sm:gap-4 md:gap-6 lg:gap-8 xl:gap-12">
          {/* Logo */}
          <div className="flex items-center flex-shrink-0 min-w-0">
            <img
              src={t.logo}
              alt="Qmobile Logo"
              className="w-auto h-10 sm:h-12 md:h-16 lg:h-20 xl:h-24 2xl:h-32 max-h-full"
            />
          </div>

          {/* Navigation Links */}
          <div className="flex items-center gap-4 sm:gap-6 md:gap-8 lg:gap-10 xl:gap-12 2xl:gap-14 flex-nowrap justify-center flex-1 min-w-0">
            <a 
              href="/join-us" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.joinUs}
            </a>
            <a 
              href="/our-story" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.ourStory}
            </a>
            <a 
              href="/marketplace" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.marketplace}
            </a>
            <a 
              href="/support" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.support}
            </a>
            <a 
              href="/blog" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.blog}
            </a>
            <a 
              href="/account" 
              className="text-white hover:opacity-80 transition-opacity whitespace-nowrap flex-shrink font-light"
              style={{ 
                fontSize: 'clamp(16px, 2vw, 36px)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t.myAccount}
            </a>

            {/* Language Switch */}
            <div className="flex items-center flex-shrink-0 ml-1 sm:ml-2">
              <button 
                onClick={toggleLanguage}
                className="flex items-center text-white hover:opacity-80 transition-opacity"
              >
                <img
                  src="/Images/2x/switch language icon@2x.png"
                  alt="Switch language"
                  className="object-contain w-8 h-8 sm:w-10 sm:h-10 md:w-12 md:h-12 lg:w-16 lg:h-16 xl:w-20 xl:h-20 2xl:w-24 2xl:h-24"
                  style={{
                    marginTop: 'clamp(10px, 2vw, 46px)'
                  }}
                />
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Navigation Row */}
        <div className="flex md:hidden justify-between items-center w-full" style={{ minWidth: 0, overflow: 'visible' }}>
          {/* Logo */}
          <div className="flex items-center flex-shrink-0" style={{ minWidth: 0, maxWidth: '50%' }}>
            <img
              src={t.logo}
              alt="Qmobile Logo"
              className="w-auto max-h-full"
              style={{
                height: 'clamp(2.5rem, 8vw, 4rem)',
                maxWidth: '100%',
                objectFit: 'contain'
              }}
            />
          </div>

          {/* Right side: Language Switch and Burger */}
          <div className="flex items-center" style={{ gap: 'clamp(8px, 2vw, 16px)' }}>
            {/* Language Switch */}
            <div className="flex items-center flex-shrink-0">
              <button 
                onClick={toggleLanguage}
                className="flex items-center text-white hover:opacity-80 transition-opacity"
                style={{ transform: 'translateY(12px)' }}
              >
                <img
                  src="/Images/2x/switch language icon@2x.png"
                  alt="Switch language"
                  className="object-contain"
                  style={{
                    width: 'clamp(3rem, 8vw, 5rem)',
                    height: 'clamp(3rem, 8vw, 5rem)'
                  }}
                />
              </button>
            </div>

            {/* Burger Menu Button */}
            <button
              onClick={toggleMobileMenu}
              className="flex items-center justify-center text-white hover:opacity-80 transition-opacity flex-shrink-0"
            >
              <img
                src="/Images/2x/hamburger@2x.png"
                alt="Menu"
                className="object-contain"
                style={{
                  width: 'clamp(2rem, 6vw, 2.5rem)',
                  height: 'clamp(2rem, 6vw, 2.5rem)',
                  minWidth: '2rem',
                  minHeight: '2rem'
                }}
              />
            </button>
          </div>
        </div>

        {/* Mobile Menu Dropdown */}
        {isMobileMenuOpen && (
          <div className="md:hidden mt-4 pb-4 border-t border-white/20">
            <div className="flex flex-col gap-4 pt-4">
              <a 
                href="/join-us" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.joinUs}
              </a>
              <a 
                href="/our-story" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.ourStory}
              </a>
              <a 
                href="/marketplace" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.marketplace}
              </a>
              <a 
                href="/support" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.support}
              </a>
              <a 
                href="/blog" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.blog}
              </a>
              <a 
                href="/account" 
                className="text-white hover:opacity-80 transition-opacity font-light text-lg"
                onClick={() => setIsMobileMenuOpen(false)}
                style={{
                  direction: isRTL ? 'rtl' : 'ltr',
                  fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
                }}
              >
                {t.myAccount}
              </a>
            </div>
          </div>
        )}


        {showTitle && (
          <div className="w-full" style={{ marginTop: 'clamp(40px, 8vw, 96px)' }}>
            <h1 
              className="text-center font-bold uppercase"
              style={{ 
                marginBottom: 'clamp(15px, 2vw, 30px)', 
                fontSize: 'clamp(2rem, 5vw, 4.7rem)',
                direction: isRTL ? 'rtl' : 'ltr',
                fontFamily: isRTL ? 'Arial, sans-serif' : 'inherit'
              }}
            >
              {t[titleKey]?.toUpperCase?.() || ''}
            </h1>
          </div>
        )}

        {children}
      </div>
    </header>
  );
};

export default ContactUsHeader;

